from collections import deque, defaultdict
def ladder_length(begin, end, words):
    words = set(words)
    if end not in words: return 0
    adj = defaultdict(set)
    for w in words:
        for i in range(len(w)):
            adj[w[:i]+'*'+w[i+1:]].add(w)
    q = deque([(begin, 1)]); seen = {begin}
    while q:
        w, d = q.popleft()
        for i in range(len(w)):
            pat = w[:i]+'*'+w[i+1:]
            for nb in adj[pat]:
                if nb == end: return d+1
                if nb not in seen:
                    seen.add(nb); q.append((nb, d+1))
    return 0

def ladder_length(begin, end, words):
    words = set(words)
    if end not in words: return 0
    def expand(front, other, words):
        nxt = set()
        for w in front:
            for i in range(len(w)):
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    t = w[:i] + c + w[i+1:]
                    if t in words:
                        if t in other: return None, True
                        nxt.add(t)
        return nxt - front, False
    f1, f2 = {begin}, {end}
    d = 1
    while f1 and f2:
        if len(f1) > len(f2): f1, f2 = f2, f1
        nw, done = expand(f1, f2, words)
        if done: return d+1
        f1 = nw; d += 1
    return 0

def solve(board):
    if not board: return
    m, n = len(board), len(board[0])
    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or board[i][j] != 'O': return
        board[i][j] = 'T'
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)): dfs(i+di, j+dj)
    for i in range(m):
        for j in (0, n-1): dfs(i, j)
    for j in range(n):
        for i in (0, m-1): dfs(i, j)
    for i in range(m):
        for j in range(n):
            if board[i][j] == 'O': board[i][j] = 'X'
            elif board[i][j] == 'T': board[i][j] = 'O'
    return board

