def find_order(numCourses, prerequisites):
    adj = [[] for _ in range(numCourses)]
    indeg = [0]*numCourses
    for a, b in prerequisites:
        adj[b].append(a); indeg[a] += 1
    q = deque([i for i in range(numCourses) if indeg[i] == 0])
    res = []
    while q:
        u = q.popleft(); res.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0: q.append(v)
    return res if len(res) == numCourses else []

def calc_equation(equations, values, queries):
    adj = {}
    for (a, b), v in zip(equations, values):
        adj.setdefault(a, []).append((b, v))
        adj.setdefault(b, []).append((a, 1/v))
    def dfs(a, b, prod, seen):
        if a not in adj: return -1
        if a == b: return prod
        seen.add(a)
        for nb, w in adj[a]:
            if nb not in seen:
                r = dfs(nb, b, prod*w, seen)
                if r != -1: return r
        return -1
    res = []
    for a, b in queries:
        res.append(dfs(a, b, 1.0, set()) if a == b else dfs(a, b, 1.0, set()))
    return res

def calc_equation(equations, values, queries):
    g = {}
    for (a, b), v in zip(equations, values):
        g.setdefault(a, {})[b] = v
        g.setdefault(b, {})[a] = 1/v
    nodes = list(g)
    for k in nodes:
        for i in nodes:
            for j in nodes:
                if i in g and k in g[i] and j in g[k]:
                    g.setdefault(i, {})[j] = g[i][k] * g[k][j]
    return [g.get(a, {}).get(b, -1.0) for a, b in queries]

def pacific_atlantic_flow(heights):
    if not heights: return []
    m, n = len(heights), len(heights[0])
    pac = [[False]*n for _ in range(m)]
    atl = [[False]*n for _ in range(m)]
    def dfs(i, j, ocean):
        if ocean[i][j]: return
        ocean[i][j] = True
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i+di, j+dj
            if 0 <= ni < m and 0 <= nj < n and heights[ni][nj] >= heights[i][j]:
                dfs(ni, nj, ocean)
    for i in range(m):
        dfs(i, 0, pac); dfs(i, n-1, atl)
    for j in range(n):
        dfs(0, j, pac); dfs(m-1, j, atl)
    res = []
    for i in range(m):
        for j in range(n):
            if pac[i][j] and atl[i][j]:
                res.append([i, j])
    return res

def pacific_atlantic(heights):
    if not heights: return []
    m, n = len(heights), len(heights[0])
    def reach(i, j):
        seen = [[False]*n for _ in range(m)]
        hit = [False, False]
        def dfs(r, c):
            if seen[r][c]: return
            seen[r][c] = True
            if r == 0 or c == 0: hit[0] = True
            if r == m-1 or c == n-1: hit[1] = True
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = r+di, c+dj
                if 0 <= ni < m and 0 <= nj < n and heights[ni][nj] <= heights[r][c]:
                    dfs(ni, nj)
        dfs(i, j)
        return hit[0] and hit[1]
    res = []
    for i in range(m):
        for j in range(n):
            if reach(i, j): res.append([i, j])
    return res

