def min_mutation(start, end, bank):
    bank = set(bank)
    if end not in bank: return -1
    q = deque([(start, 0)]); seen = {start}
    while q:
        g, d = q.popleft()
        if g == end: return d
        for i in range(len(g)):
            for ch in 'ACGT':
                ng = g[:i] + ch + g[i+1:]
                if ng in bank and ng not in seen:
                    seen.add(ng); q.append((ng, d+1))
    return -1

def update_matrix(mat):
    from collections import deque
    m, n = len(mat), len(mat[0])
    q = deque(); dist = [[-1]*n for _ in range(m)]
    for i in range(m):
        for j in range(n):
            if mat[i][j] == 0:
                dist[i][j] = 0; q.append((i, j))
    while q:
        i, j = q.popleft()
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i+di, j+dj
            if 0 <= ni < m and 0 <= nj < n and dist[ni][nj] == -1:
                dist[ni][nj] = dist[i][j] + 1; q.append((ni, nj))
    return dist

def update_matrix_dp(mat):
    m, n = len(mat), len(mat[0])
    INF = m + n
    for i in range(m):
        for j in range(n):
            if mat[i][j] != 0:
                top = mat[i-1][j] + 1 if i > 0 else INF
                left = mat[i][j-1] + 1 if j > 0 else INF
                mat[i][j] = min(INF, top, left)
    for i in range(m-1, -1, -1):
        for j in range(n-1, -1, -1):
            if mat[i][j] != 0:
                bot = mat[i+1][j] + 1 if i < m-1 else INF
                right = mat[i][j+1] + 1 if j < n-1 else INF
                mat[i][j] = min(mat[i][j], bot, right)
    return mat

def find_circle_num(isConnected):
    n = len(isConnected)
    par = list(range(n))
    def find(x):
        while par[x] != x:
            par[x] = par[par[x]]; x = par[x]
        return x
    comps = n
    for i in range(n):
        for j in range(i+1, n):
            if isConnected[i][j]:
                ri, rj = find(i), find(j)
                if ri != rj:
                    par[rj] = ri; comps -= 1
    return comps

def find_circle_num_dfs(isConnected):
    n = len(isConnected)
    seen = [False]*n
    def dfs(u):
        seen[u] = True
        for v in range(n):
            if isConnected[u][v] and not seen[v]:
                dfs(v)
    cnt = 0
    for u in range(n):
        if not seen[u]:
            cnt += 1; dfs(u)
    return cnt

def max_area_of_island(grid):
    m, n = len(grid), len(grid[0])
    best = 0
    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] == 0:
            return 0
        grid[i][j] = 0
        return 1 + dfs(i+1,j) + dfs(i-1,j) + dfs(i,j+1) + dfs(i,j-1)
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                best = max(best, dfs(i, j))
    return best

def max_area_of_island_bfs(grid):
    from collections import deque
    m, n = len(grid), len(grid[0]); best = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                q = deque([(i, j)]); grid[i][j] = 0; area = 0
                while q:
                    r, c = q.popleft(); area += 1
                    for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == 1:
                            grid[nr][nc] = 0; q.append((nr, nc))
                best = max(best, area)
    return best

def flood_fill(image, sr, sc, color):
    m, n = len(image), len(image[0])
    old = image[sr][sc]
    if old == color: return image
    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or image[i][j] != old:
            return
        image[i][j] = color
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            dfs(i+di, j+dj)
    dfs(sr, sc)
    return image

def flood_fill_bfs(image, sr, sc, color):
    from collections import deque
    m, n = len(image), len(image[0])
    old = image[sr][sc]
