            ni, nj = i+di, j+dj
            if 0 <= ni < m and 0 <= nj < n and image[ni][nj] == old:
                image[ni][nj] = color; q.append((ni, nj))
    return image

def network_delay_time_floyd(times, n, k):
    INF = 10**9
    dist = [[INF]*n for _ in range(n)]
    for i in range(n): dist[i][i] = 0
    for u, v, w in times:
        dist[u-1][v-1] = w
    for p in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][p] + dist[p][j] < dist[i][j]:
                    dist[i][j] = dist[i][p] + dist[p][j]
    mx = max(dist[k-1])
    return -1 if mx == INF else mx

from collections import deque
def snakes_and_ladders(board):
    n = len(board)
    def idx(s):
        r, c = divmod(s-1, n)
        if r % 2: c = n-1-c
        return n-1-r, c
    q = deque([(1, 0)]); seen = {1}
    while q:
        s, d = q.popleft()
        if s == n*n: return d
        for k in range(1, 7):
            nxt = s + k
            if nxt > n*n: continue
            r, c = idx(nxt)
            if board[r][c] != -1: nxt = board[r][c]
            if nxt not in seen:
                seen.add(nxt); q.append((nxt, d+1))
    return -1

def oranges_rotting(grid):
    from collections import deque
    m, n = len(grid), len(grid[0])
    q = deque(); fresh = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2: q.append((i,j))
            elif grid[i][j] == 1: fresh += 1
    mins = 0
    while q and fresh:
        for _ in range(len(q)):
            i, j = q.popleft()
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                    grid[ni][nj] = 2; fresh -= 1; q.append((ni,nj))
        mins += 1
    return mins if fresh == 0 else -1

